{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Aromatic sessions that may support balance</title>
  <meta name="description" content="Aromatherapy sessions and intensive programs that may support calm, focus, and reset in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <div class="brand">
        <div class="mark" aria-hidden="true">🜁</div>
        <div class="titles">
          <strong class="name">{{BUSINESS_NAME}}</strong>
          <small class="sub">Bespoke aromatic care in {{CITY}}, {{STATE}}</small>
        </div>
      </div>
      <nav class="nav">
        <a href="services.html">Offerings</a>
        <a href="blends.html">Signature Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="about.html">Our Story</a>
        <a href="book.html" class="cta primary">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" id="hero">
      <div class="wrap">
        <div class="hero-grid">
          <div class="hero-copy">
            <h1>Intentional scent work for subtle shifts of attention</h1>
            <p class="lead">Guided aromatic sessions and an intensive pathway that may support emotional regulation, clearer mornings, and gentler evenings — personalised to how you move through your day.</p>
            <p class="meta">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
            <div class="hero-actions">
              <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
              <a class="btn" href="services.html">Explore Offerings</a>
            </div>
          </div>
          <div class="hero-art" aria-hidden="true">
            <svg viewBox="0 0 200 200" class="orb">
              <defs>
                <linearGradient id="g1" x1="0" x2="1">
                  <stop offset="0" stop-color="#f7e9ff"/>
                  <stop offset="1" stop-color="#e6fff4"/>
                </linearGradient>
              </defs>
              <circle cx="100" cy="100" r="80" fill="url(#g1)" opacity="0.9"/>
              <g fill="#fff" opacity="0.05">
                <circle cx="60" cy="80" r="40"/>
                <circle cx="140" cy="120" r="30"/>
              </g>
            </svg>
          </div>
        </div>
      </div>
    </section>

    <!-- What to expect (intensive model) -->
    <section class="what-to-expect" id="what-to-expect">
      <div class="wrap">
        <h2>What to expect — Intensive aromatic pathway</h2>
        <p class="intro">Our intensive program is paced across a focused timeline so you receive concentrated guidance, a custom blend plan, and at-home practices that may support integration between sessions.</p>
        <ul class="expect-list">
          <li><strong>Initial Consultation:</strong> Intake, safety review, and sensory mapping (patch test guidance included).</li>
          <li><strong>Two Guided Sessions:</strong> In-clinic aromatic sessions with breathing and journaling prompts that may support noticing shifts.</li>
          <li><strong>Personal Blend & Guide:</strong> A sealed sample, dilution notes, and a 4-week usage support schedule.</li>
        </ul>
        <p class="note">Safety note: Never ingest essential oils. Use dilution guidelines and consult a healthcare provider if pregnant or nursing. Keep oils away from pets and perform a patch test before regular use.</p>
      </div>
    </section>

    <!-- Aroma Wheel (interactive) -->
    <section class="aroma-wheel" id="aroma-wheel">
      <div class="wrap">
        <h2>Aroma wheel — explore top, middle, and base notes</h2>
        <p class="intro">Hover or tap each slice to learn about common notes and how they may support different moods.</p>
        <div class="wheel-grid">
          <div class="wheel-stage" aria-hidden="false">
            <svg id="wheel-svg" viewBox="0 0 200 200" role="img" aria-label="Aroma wheel">
              <g class="slices">
                <path class="slice top" d="M100 100 L200 100 A100 100 0 0 0 100 0 Z" data-category="top" tabindex="0"></path>
                <path class="slice middle" d="M100 100 L100 0 A100 100 0 0 0 0 100 Z" data-category="middle" tabindex="0"></path>
                <path class="slice base" d="M100 100 L0 100 A100 100 0 0 0 100 200 Z" data-category="base" tabindex="0"></path>
                <circle cx="100" cy="100" r="35" class="center"/>
              </g>
              <text x="100" y="106" text-anchor="middle" class="wheel-label">Notes</text>
            </svg>
          </div>
          <div class="wheel-info" id="wheel-info" aria-live="polite">
            <h3 id="wheel-title">Hover a slice</h3>
            <p id="wheel-desc">Top notes are bright and often first to be noticed. Middle notes round a blend out. Base notes give depth and lingering support.</p>
            <ul id="wheel-list" class="notes-list"></ul>
          </div>
        </div>
      </div>
    </section>

    <!-- Proof Gallery (rotating testimonials + badges) -->
    <section class="proof-gallery" id="proof-gallery">
      <div class="wrap">
        <h2>Proof & trust</h2>
        <p class="intro">Client reflections and small-batch collaborations that help us stay craft-forward.</p>
        <div class="gallery-row">
          <div class="testimonial" id="testimonial">
            <blockquote id="quote">"A quiet, careful experience that helped me notice small shifts in focus."</blockquote>
            <cite id="author">— A client, {{CITY}}</cite>
          </div>
          <div class="badges" aria-hidden="false" id="badges">
            <div class="badge" data-tooltip="Certified Aromatherapist Network">CAN</div>
            <div class="badge" data-tooltip="Ethical Harvest Collective">EHC</div>
            <div class="badge" data-tooltip="Local Small Business Guild">LSB</div>
          </div>
        </div>
      </div>
    </section>

    <!-- Objections / FAQ / Safety -->
    <section class="objections" id="objections">
      <div class="wrap">
        <h2>Questions & safety notes</h2>
        <div class="qa-grid">
          <div class="qa">
            <h4>Is aromatherapy safe for everyone?</h4>
            <p>We prioritise safety. We will review pregnancy, medication, and pet exposure. If you are pregnant, nursing, or on medication, consult a provider and share that in intake.</p>
          </div>
          <div class="qa">
            <h4>How should I dilute oils?</h4>
            <p>We recommend dilution guides specific to adult topical use, typically 0.5–3% for home blends unless directed otherwise. Always perform a patch test before regular use.</p>
          </div>
          <div class="qa">
            <h4>What about pets?</h4>
            <p>Many essential oils can be irritants to animals. Keep oils away from pets, avoid direct topical application to animals, and use diffusers with caution in shared spaces.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Final CTA -->
    <section class="cta" id="final-cta">
      <div class="wrap">
        <h2>Ready to start a focused aromatic plan?</h2>
        <p>Book a conversation to discuss tailoring an intensive pathway that may support steadier days.</p>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn" href="contact.html">Ask a safety question</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <small>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Aromatic practice in {{CITY}}, {{STATE}}</small>
      </div>
      <div class="foot-right">
        <a href="privacy.html">Privacy</a>
        <a href="contact.html">Contact</a>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
